class Solution:
    def moveSubTree(self, root: 'Node', p: 'Node', q: 'Node') -> 'Node':
        parent = {root: None}
        stack = [root]
        while stack:
            node = stack.pop()
            for ch in node.children:
                parent[ch] = node
                stack.append(ch)

        if parent[p] is q:
            return root

        q_in_p = False
        st = [p]
        while st:
            node = st.pop()
            if node is q:
                q_in_p = True
                break
            st.extend(node.children)

        parent_p = parent[p]
        if parent_p is not None:
            parent_p.children.remove(p)
        if q_in_p:
            parent[q].children.remove(q)
        q.children.append(p)
        return root if parent_p is not None else q

