class Solution {
public:
    Node* moveSubTree(Node* root, Node* p, Node* q) {
        unordered_map<Node*, Node*> parent;
        vector<Node*> st{root};
        parent[root] = nullptr;
        while (!st.empty()) {
            Node* node = st.back();
            st.pop_back();
            for (Node* ch : node->children) {
                parent[ch] = node;
                st.push_back(ch);
            }
        }
        if (parent[p] == q) return root;

        bool qInP = false;
        vector<Node*> st2{p};
        while (!st2.empty()) {
            Node* node = st2.back();
            st2.pop_back();
            if (node == q) { qInP = true; break; }
            for (Node* ch : node->children) st2.push_back(ch);
        }

        Node* parentP = parent[p];
        if (parentP) parentP->children.erase(find(parentP->children.begin(), parentP->children.end(), p));
        if (qInP) parent[q]->children.erase(find(parent[q]->children.begin(), parent[q]->children.end(), q));
        q->children.push_back(p);
        return parentP ? root : q;
    }
};

