class Solution {
    public Node moveSubTree(Node root, Node p, Node q) {
        Map<Node, Node> parent = new HashMap<>();
        parent.put(root, null);
        Deque<Node> stack = new ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            Node node = stack.pop();
            for (Node ch : node.children) {
                parent.put(ch, node);
                stack.push(ch);
            }
        }
        if (parent.get(p) == q) return root;

        boolean qInP = false;
        Deque<Node> st = new ArrayDeque<>();
        st.push(p);
        while (!st.isEmpty()) {
            Node node = st.pop();
            if (node == q) { qInP = true; break; }
            for (Node ch : node.children) st.push(ch);
        }

        Node parentP = parent.get(p);
        if (parentP != null) parentP.children.remove(p);
        if (qInP) parent.get(q).children.remove(q);
        q.children.add(p);
        return parentP == null ? q : root;
    }
}

