var moveSubTree = function(root, p, q) {
    const parent = new Map([[root, null]]);
    const stack = [root];
    while (stack.length) {
        const node = stack.pop();
        for (const ch of node.children) {
            parent.set(ch, node);
            stack.push(ch);
        }
    }
    if (parent.get(p) === q) return root;

    let qInP = false;
    const st = [p];
    while (st.length) {
        const node = st.pop();
        if (node === q) { qInP = true; break; }
        for (const ch of node.children) st.push(ch);
    }

