        if (parentP) parentP->children.erase(find(parentP->children.begin(), parentP->children.end(), p));
        if (qInP) parentQ->children.erase(find(parentQ->children.begin(), parentQ->children.end(), q));
        q->children.push_back(p);
        return parentP ? root : q;
    }
};

